<script setup lang="ts">import {computed,ref} from 'vue';import StatCards from '../../components/common/StatCards.vue';import EntityTable from '../../components/common/EntityTable.vue';const props=defineProps<{kind:'overview'|'invoices'|'receivables'|'payables'|'collection'}>();const keyword=ref('');const config={overview:{title:'财务概览',kicker:'FINANCE OVERVIEW',columns:['指标','本期金额','环比','状态']},invoices:{title:'发票管理',kicker:'FINANCE INVOICES',columns:['发票编号','客户','金额','状态']},receivables:{title:'应收账款',kicker:'RECEIVABLES',columns:['客户','应收金额','到期日期','状态']},payables:{title:'应付账款',kicker:'PAYABLES',columns:['供应商','应付金额','付款日期','状态']},collection:{title:'收款管理',kicker:'PAYMENT COLLECTION',columns:['客户','收款金额','收款日期','核销状态']}};const current=computed(()=>config[props.kind]);const rows=ref<Array<Record<string,unknown>>>([]);const filtered=computed(()=>{const key=keyword.value.trim().toLowerCase();return key?rows.value.filter(row=>Object.values(row).some(v=>String(v??'').toLowerCase().includes(key))):rows.value});</script>
<template><section class="crm-view"><div class="section-heading"><div><span class="eyebrow">{{current.kicker}}</span><h2>{{current.title}}</h2></div><button class="primary">新增记录</button></div><StatCards :items="[{label:'本月收入',value:'—'},{label:'本月支出',value:'—'},{label:'待回款',value:'—'},{label:'利润率',value:'—'}]"/><div class="toolbar"><input v-model="keyword" :placeholder="`搜索${current.title}`"/><span>{{filtered.length}} 条记录</span></div><EntityTable v-if="filtered.length" :columns="current.columns" :rows="filtered" :cell="(row,index)=>Object.values(row)[index]||'—'"/><div v-else class="state">{{current.title}}页面已完成 Vue 迁移，等待接口数据接入。</div></section></template>
